import { beforeEach, expect, test, vi } from 'vitest'
import { createPinia, setActivePinia } from 'pinia'
import { createFloodStore } from '../src/stores/flood'
import { request } from '../src/utils/request'

vi.mock('../src/utils/request', async () => {
  const actual = await vi.importActual<typeof import('../src/utils/request')>('../src/utils/request')
  return { ...actual, request: vi.fn() }
})

const memory = new Map<string, unknown>()
const storage = { get: (k: string) => memory.get(k), set: (k: string, v: unknown) => { memory.set(k, structuredClone(v)) } }
beforeEach(() => { memory.clear(); setActivePinia(createPinia()) })

const pageVo = (rows: Record<string, unknown>[], total = rows.length) => ({ total, rows, code: 200, msg: 'ok' })

test('inspectionRowToRecord 按 bizState 映射状态：0=待提交，其余=已提交', async () => {
  const store = createFloodStore(storage)()
  ;(request as unknown as vi.Mock).mockResolvedValue({ inspectionId: '100', inspectionStage: '2', bizState: '0', createTime: '2026-11-01T00:00:00Z' })
  const draft = await store.getRecordAsync('100', 'pre')
  expect(draft?.status).toBe('draft')
  ;(request as unknown as vi.Mock).mockResolvedValue({ inspectionId: '101', inspectionStage: '2', bizState: '1', createTime: '2026-11-01T00:00:00Z' })
  const submitted = await store.getRecordAsync('101', 'pre')
  expect(submitted?.status).toBe('submitted')
  // 缺失 bizState 时回落为已提交，避免待提交误判
  ;(request as unknown as vi.Mock).mockResolvedValue({ inspectionId: '102', inspectionStage: '2', createTime: '2026-11-01T00:00:00Z' })
  const fallback = await store.getRecordAsync('102', 'pre')
  expect(fallback?.status).toBe('submitted')
})

test('fetchHistoryRemote 按 status 透传 bizStates 给后端做服务端筛选', async () => {
  const store = createFloodStore(storage, 'remote')()
  const captured: string[] = []
  ;(request as unknown as vi.Mock).mockImplementation(async (url: string) => {
    captured.push(url)
    return pageVo([{ inspectionId: '1', inspectionStage: '2', bizState: '0', createTime: '2026-11-01T00:00:00Z' }])
  })
  const draftRes = await store.fetchHistoryPage({ pageNum: 1, pageSize: 10, kinds: ['pre'], status: 'draft' })
  expect(decodeURIComponent(captured[0])).toContain('bizStates=0')
